// generated by tcacomp — deterministic output; do not edit
#include "tca/runtime.h"

template <typename T>
__device__ static __forceinline__ T Axpy3Combine0(T p0, T p1) {
  return (p0 + p1);
}

// Axpy3: launch 16 CTAs x 64 threads (derived from the loop annotations: gridDim = max over LNTs of CTA LoC products, blockDim = (max warp-K product) x 32 — the runtime validates)
// dynamic SMEM pool: 8 B (v0: disjoint offsets, zero reuse)
namespace {

__global__ void __launch_bounds__(64) Axpy3(uint32_t R, uint32_t C, uint32_t K, const float* __restrict__ x, const float* __restrict__ z, float* __restrict__ out, float alpha, float beta, float gamma) {
  tca::rt::TensorView<const float, 3u> x_v(x, R, C, K);
  tca::rt::TensorView<const float, 3u> z_v(z, R, C, K);
  tca::rt::TensorView<float, 2u> out_v(out, R, C);
  // dynamic SMEM pool (8 B): one pool, disjoint v0 offsets — the future RA pass overlaps them
  extern __shared__ __align__(16) char tca_smem[];
  tca::rt::Frag<float, 2u, 32u, 1u> tca_f0;
  tca::rt::Frag<float, 2u, 32u, 1u> tca_f1;

  tca::rt::KernelInfo kinfo;
  // LNT #0: R=CTA(T=256,LoC=16) C=sequential(T=32,LoC=1) K=thread/warp(T=32,LoC=2) dim=thread/warp(LoC=64) dim=sequential(LoC=1) K=sequential(T=32,LoC=1)
  {
    // CTA-space mapping (absolute LoC per dim: 16u — the factorization this nest remaps)
    tca::rt::GridMapping grid_map0(kinfo, 1u, 16u);
    // per-CTA thread-space mapping (absolute warp counts K per dim: 2u)
    tca::rt::ThreadMapping thread_map1(kinfo, 1u, 2u);
    auto v0 = alpha;
    auto v1 = beta;
    auto c0 = 0.0f;
    auto v2 = gamma;
    auto c1 = 0u;
    auto v3 = R;
    auto c2 = 1u;
    auto v4 = C;
    auto c3 = 2u;
    auto v5 = K;
    auto v6 = grid_map0.index(0u);
    auto c4 = 256u;
    auto v7 = (v6 * c4);
    auto c5 = 32u;
    auto v8 = thread_map1.index(0u);
    auto v9 = (v8 * c5);
    auto v10 = thread_map1.lane_id();
    auto v11 = (v10 + c2);
    auto v12 = (v11 * c2);
    auto v13 = (v10 * c2);
    // warp reduction — the combiner is runtime-owned; per-element brackets [Init → reduced-dim walks (Reduce(value)) → Combine]
    tca::rt::WarpReducer<float> reducer0(c0, Axpy3Combine0, thread_map1, tca::rt::SmemView<float, 1u>(reinterpret_cast<float*>(tca_smem + 0u), 2u));
    // @R tile-between rounds — CTA, T=256, LoC=16 (map dim 0)
    for (auto R_it0 = tca::rt::CtaIterator(grid_map0, 0u, 16u, 0u, 4096u, v3); R_it0.Has(); R_it0.Next()) {
      auto v14 = (v7 + R_it0.Index());
      auto v15 = tca::rt::umin(v14, v3);
      auto v16 = (v3 - v15);
      auto v17 = tca::rt::umin(c4, v16);
      // @C tile-between rounds — sequential, T=32, LoC=1
      for (auto C_it1 = tca::rt::SeqIterator(0u, 32u, v4); C_it1.Has(); C_it1.Next()) {
        auto v18 = tca::rt::umin(C_it1.Index(), v4);
        auto v19 = (v4 - v18);
        auto v20 = tca::rt::umin(c5, v19);
        // @R walk — sequential, LoC=1
        for (auto R_it2 = tca::rt::SeqIterator(0u, 1u, v17); R_it2.Has(); R_it2.Next()) {
          auto v21 = (v14 + R_it2.Index());
          // @C walk — sequential, LoC=1
          for (auto C_it3 = tca::rt::SeqIterator(0u, 1u, v20); C_it3.Has(); C_it3.Next()) {
            // per-element bracket opens (argument-free; re-initializes from the construction-time init)
            reducer0.Init();
            // @K tile-between rounds — thread/warp, T=32, LoC=2 (map dim 0)
            for (auto K_it4 = tca::rt::ThrIterator(thread_map1, 0u, 2u, 0u, 64u, v5); K_it4.Has(); K_it4.Next()) {
              auto v22 = (v9 + K_it4.Index());
              auto v23 = tca::rt::umin(v22, v5);
              auto v24 = (v5 - v23);
              auto v25 = tca::rt::umin(c5, v24);
              auto v26 = tca::rt::umin(v12, v25);
              auto v27 = (v22 + v13);
              // per-thread tile fill of x (LoadTileThread) — no synchronization
              tca::rt::LoadTileThread(thread_map1, tca_f0, tca::rt::TensorWindow(x_v, v21, C_it1.Index(), v27));
              // per-thread tile fill of z (LoadTileThread) — no synchronization
              tca::rt::LoadTileThread(thread_map1, tca_f1, tca::rt::TensorWindow(z_v, v21, C_it1.Index(), v27));
              // @K inside walk (tile elements) — T=32
              for (auto K_it5 = tca::rt::SeqIterator((v10 * c2), 1u, v26); K_it5.Has(); K_it5.Next()) {
                auto v28 = (K_it5.Index() - v13);
                auto v29 = tca_f0.Get(C_it3.Index(), v28);
                auto v30 = (v0 * v29);
                auto v31 = tca_f1.Get(C_it3.Index(), v28);
                auto v32 = (v1 * v31);
                auto v33 = (v30 + v32);
                reducer0.Reduce(v33);
              }
            }
            // per-element combine — every participant receives the element's final value
            auto v34 = reducer0.Combine();
            auto v35 = tanhf(v34);
            auto v36 = (v2 * v35);
            auto v37 = (v34 + v36);
            // single-owner store — the element's owner thread writes (R2/R3)
            if (thread_map1.is_first_in_cta()) {
              out_v.Set(v37, (v14 + R_it2.Index()), (C_it1.Index() + C_it3.Index()));
            }
          }
        }
      }
    }
  }
}

}  // namespace

void Axpy3Launch(const tca::Tensor<float, 3u>& x, const tca::Tensor<float, 3u>& z, tca::Tensor<float, 2u>& out, float alpha, float beta, float gamma, cudaStream_t tca_stream) {
  const uint32_t R = x.Dim(0u);
  const uint32_t C = x.Dim(1u);
  const uint32_t K = x.Dim(2u);
  TCA_REQUIRE(z.Dim(0u) == R, "z.Dim(0) must equal R (dim R)");
  TCA_REQUIRE(z.Dim(1u) == C, "z.Dim(1) must equal C (dim C)");
  TCA_REQUIRE(z.Dim(2u) == K, "z.Dim(2) must equal K (dim K)");
  TCA_REQUIRE(out.Dim(0u) == R, "out.Dim(0) must equal R (dim R)");
  TCA_REQUIRE(out.Dim(1u) == C, "out.Dim(1) must equal C (dim C)");
  tca::rt::ValidateLaunch(dim3(16u, 1u, 1u), dim3(64u, 1u, 1u), 8u, 512u);
  Axpy3<<<dim3(16u, 1u, 1u), dim3(64u, 1u, 1u), 8u, tca_stream>>>(R, C, K, x.Data(), z.Data(), out.Data(), alpha, beta, gamma);
  TCA_CUDA_CHECK(cudaGetLastError());
}
